SpeedLimitRequest speed_request()
{
  SpeedLimitRequest request;
  request.normal_speed_mps = 20.0;
  request.global_hard_cap_mps = 40.0;
  return request;
}

RecoveryPolicyRequest recovery_request()
{
  RecoveryPolicyRequest request;
  request.configured_velocity_limit_mps = 3.0;
  request.elapsed_sec = 0.5;
  request.traveled_distance_m = 0.5;
  request.target_distance_m = 10.0;
  request.lateral_error_m = 0.6;
  request.lateral_completion_m = 0.2;
  request.stalled_sec = 0.0;
  request.stall_timeout_sec = 1.0;
  request.timeout_sec = 5.0;
  return request;
}

FollowSpeedLimitRequest follow_speed_request()
{
  FollowSpeedLimitRequest request;
  request.enabled = true;
  request.front_distance_m = 5.0;
  request.activation_distance_m = 5.0;
  request.front_speed_mps = 3.0;
  request.moving_front_speed_threshold_mps = 1.0;
  request.moving_front_speed_margin_mps = 0.8;
  request.moving_front_target_distance_m = 2.5;
  request.moving_front_recovery_speed_margin_mps = 0.5;
  request.moving_front_distance_gain = 1.0;
  request.slow_front_distance_limit_mps = 2.3;
  request.slow_front_velocity_cap_mps = 3.0;
  request.maximum_speed_mps = 20.0;
  return request;
}

TEST(V2XReceiptAge, AcceptsCurrentAndSmallFutureReceipt)
{
  EXPECT_TRUE(is_v2x_receipt_age_fresh(0.0, 1.0, 0.05));
  EXPECT_TRUE(is_v2x_receipt_age_fresh(1.0, 1.0, 0.05));
  EXPECT_TRUE(is_v2x_receipt_age_fresh(-0.035, 1.0, 0.05));
  EXPECT_TRUE(is_v2x_receipt_age_fresh(-0.05, 1.0, 0.05));
}

TEST(V2XReceiptAge, RejectsStaleInvalidAndExcessivelyFutureReceipt)
{
  EXPECT_FALSE(is_v2x_receipt_age_fresh(-0.050001, 1.0, 0.05));
  EXPECT_FALSE(is_v2x_receipt_age_fresh(1.000001, 1.0, 0.05));
  EXPECT_FALSE(is_v2x_receipt_age_fresh(
    std::numeric_limits<double>::quiet_NaN(), 1.0, 0.05));
  EXPECT_FALSE(is_v2x_receipt_age_fresh(
    std::numeric_limits<double>::infinity(), 1.0, 0.05));
  EXPECT_FALSE(is_v2x_receipt_age_fresh(0.0, -1.0, 0.05));
  EXPECT_FALSE(is_v2x_receipt_age_fresh(0.0, 1.0, -0.05));
}

TEST(V2XPeerIdentityTracker, LearnsPeersAndAcceptsOrderIndependentCompleteSet)
{
  V2XPeerIdentityTracker tracker;
  EXPECT_TRUE(tracker.observe_valid_message({"P2", "P3"}));
  EXPECT_EQ(tracker.learned_vehicle_count(), 2U);
  EXPECT_TRUE(tracker.is_complete({"P3", "P2"}));
}

TEST(V2XPeerIdentityTracker, RejectsPartialOrSameCountDifferentIdentity)
{
  V2XPeerIdentityTracker tracker;
  ASSERT_TRUE(tracker.observe_valid_message({"P2", "P3"}));
  EXPECT_FALSE(tracker.is_complete({"P2"}));
  EXPECT_FALSE(tracker.is_complete({"P2", "P4"}));
}

TEST(V2XPeerIdentityTracker, ExpandsTheKnownSetWhenAValidPeerAppears)
{
  V2XPeerIdentityTracker tracker;
  ASSERT_TRUE(tracker.observe_valid_message({"P2"}));
  ASSERT_TRUE(tracker.observe_valid_message({"P2", "P3"}));
  EXPECT_EQ(tracker.learned_vehicle_count(), 2U);
  EXPECT_FALSE(tracker.is_complete({"P2"}));
  EXPECT_TRUE(tracker.is_complete({"P2", "P3"}));
}

TEST(V2XPeerIdentityTracker, InvalidAndEmptyEvidenceCannotAuthorizeMotion)
{
  V2XPeerIdentityTracker tracker;
  EXPECT_TRUE(tracker.observe_valid_message({}));
  EXPECT_FALSE(tracker.is_complete({}));
  EXPECT_FALSE(tracker.observe_valid_message({"P2", "P2"}));
  EXPECT_FALSE(tracker.observe_valid_message({""}));
  EXPECT_EQ(tracker.learned_vehicle_count(), 0U);
}

TEST(V2XPeerIdentityTracker, ResetClearsTheRaceSessionIdentitySet)
{
  V2XPeerIdentityTracker tracker;
  ASSERT_TRUE(tracker.observe_valid_message({"P2"}));
  tracker.reset();
  EXPECT_EQ(tracker.learned_vehicle_count(), 0U);
  EXPECT_FALSE(tracker.is_complete({"P2"}));
}

TEST(V2XOpponentMotionFilter, SmoothsVelocityAndBoundsAcceleration)
{
  OpponentMotionFilterRequest request;
  request.previous_estimate_valid = true;
  request.previous_velocity_x_mps = 3.0;
  request.previous_acceleration_x_mps2 = 0.0;
  request.observed_velocity_x_mps = 7.0;
  request.sample_interval_sec = 0.5;
  request.velocity_gain = 0.25;
  request.acceleration_gain = 1.0;
  request.maximum_acceleration_mps2 = 1.5;

  const auto result = update_opponent_motion_filter(request);
  ASSERT_TRUE(result.valid);
  EXPECT_NEAR(result.velocity_x_mps, 4.0, 1e-9);
  EXPECT_NEAR(result.velocity_y_mps, 0.0, 1e-9);
  EXPECT_NEAR(result.acceleration_x_mps2, 1.5, 1e-9);
  EXPECT_NEAR(result.acceleration_y_mps2, 0.0, 1e-9);
}

TEST(V2XOpponentMotionFilter, InitializesFirstVelocityWithoutAccelerationSpike)
{
  OpponentMotionFilterRequest request;
  request.observed_velocity_x_mps = 3.0;
  request.observed_velocity_y_mps = 0.5;
  request.sample_interval_sec = 1.0;
  request.velocity_gain = 0.35;
  request.acceleration_gain = 0.25;
  request.maximum_acceleration_mps2 = 3.0;

  const auto result = update_opponent_motion_filter(request);
  ASSERT_TRUE(result.valid);
  EXPECT_DOUBLE_EQ(result.velocity_x_mps, 3.0);
  EXPECT_DOUBLE_EQ(result.velocity_y_mps, 0.5);
  EXPECT_DOUBLE_EQ(result.acceleration_x_mps2, 0.0);
  EXPECT_DOUBLE_EQ(result.acceleration_y_mps2, 0.0);
}

