TEST(V2XOvertakeCoreMissionOwnership, DirectPassResumeRequiresSameSideClearCorridor)
{
  PausedPassDirectResumeRequest request;
  request.resuming_paused_mission = true;
  request.mission_side_sign = 1;
  request.behavior_side_sign = 1;
  request.execution_corridor_valid = true;
  request.target_seen = true;
  request.target_lateral_prediction_valid = true;
  request.target_relative_lateral_m = -1.60;
  request.target_predicted_relative_lateral_m = -1.70;
  request.required_lateral_clearance_m = 1.50;
  request.current_lateral_m = 0.80;
  request.goal_lateral_m = 1.00;

  EXPECT_TRUE(can_resume_paused_pass_directly(request));

  request.behavior_side_sign = -1;
  EXPECT_FALSE(can_resume_paused_pass_directly(request));
  request.behavior_side_sign = 1;

  request.goal_lateral_m = -0.20;
  EXPECT_FALSE(can_resume_paused_pass_directly(request));
  request.goal_lateral_m = 1.00;

  request.goal_lateral_m = 0.70;
  EXPECT_FALSE(can_resume_paused_pass_directly(request));
  request.goal_lateral_m = 1.00;

  request.target_relative_lateral_m = -1.49;
  EXPECT_FALSE(can_resume_paused_pass_directly(request));
  request.target_relative_lateral_m = -1.60;

  request.target_position_jump = true;
  EXPECT_FALSE(can_resume_paused_pass_directly(request));
  request.target_position_jump = false;

  request.target_relative_lateral_m = 1.60;
  EXPECT_FALSE(can_resume_paused_pass_directly(request));
  request.target_relative_lateral_m = -1.60;

  request.target_lateral_prediction_valid = false;
  EXPECT_FALSE(can_resume_paused_pass_directly(request));
  request.target_lateral_prediction_valid = true;

  request.target_predicted_relative_lateral_m = -1.20;
  EXPECT_FALSE(can_resume_paused_pass_directly(request));
  request.target_predicted_relative_lateral_m = -1.70;

}

TEST(V2XOvertakeCoreMissionOwnership, DirectPassResumeDoesNotDeadlockOnMeasuredSpeedDeficit)
{
  // 20260801-081138/d1: lateral admission was already safe while ego was
  // 1.61 m/s slower. FollowPrepare cannot create closing speed while waiting
  // for a condition that only the Pass speed policy can resolve.
  PausedPassDirectResumeRequest request;
  request.resuming_paused_mission = true;
  request.mission_side_sign = -1;
  request.behavior_side_sign = -1;
  request.execution_corridor_valid = true;
  request.target_seen = true;
  request.target_lateral_prediction_valid = true;
  request.target_relative_lateral_m = 1.84;
  request.target_predicted_relative_lateral_m = 2.60;
  request.required_lateral_clearance_m = 1.50;
  request.current_lateral_m = -0.64;
  request.goal_lateral_m = -0.64;

  EXPECT_TRUE(can_resume_paused_pass_directly(request));
}

TEST(V2XOvertakeCoreMissionOwnership, DirectPassResumeMirrorsRightSidePrediction)
{
  PausedPassDirectResumeRequest request;
  request.resuming_paused_mission = true;
  request.mission_side_sign = -1;
  request.behavior_side_sign = -1;
  request.execution_corridor_valid = true;
  request.target_seen = true;
  request.target_lateral_prediction_valid = true;
  request.target_relative_lateral_m = 1.70;
  request.target_predicted_relative_lateral_m = 1.80;
  request.required_lateral_clearance_m = 1.50;
  request.current_lateral_m = -0.80;
  request.goal_lateral_m = -1.00;

  EXPECT_TRUE(can_resume_paused_pass_directly(request));

  request.target_predicted_relative_lateral_m = 1.20;
  EXPECT_FALSE(can_resume_paused_pass_directly(request));
}

TEST(V2XOvertakeCoreMissionOwnership, SafetyBrakePauseResumesOriginalExecution)
{
  PausedExecutionResumeRequest request;
  request.safety_brake_pause = true;
  request.origin = PausedExecutionOrigin::ShiftOut;
  request.validated_frozen_path = true;
  request.mission_side_valid = true;
  request.body_clear_deadline_checked = true;
  request.body_clear_deadline_feasible = true;
  request.target_seen = true;

  EXPECT_EQ(
    resolve_paused_execution_resume(request),
    PausedExecutionResumeAction::ResumeShiftOut);

  request.origin = PausedExecutionOrigin::Pass;
  EXPECT_EQ(
    resolve_paused_execution_resume(request),
    PausedExecutionResumeAction::ResumeShiftOut);

  request.direct_pass_lateral_clear = true;
  EXPECT_EQ(
    resolve_paused_execution_resume(request),
    PausedExecutionResumeAction::ResumePass);

  // Once current/predicted lateral geometry is already clear, the original
  // ShiftOut body-clear deadline no longer needs to be re-established.
  request.body_clear_deadline_checked = false;
  request.body_clear_deadline_feasible = false;
  EXPECT_EQ(
    resolve_paused_execution_resume(request),
    PausedExecutionResumeAction::ResumePass);

  request.direct_pass_lateral_clear = false;
  EXPECT_EQ(
    resolve_paused_execution_resume(request),
    PausedExecutionResumeAction::Hold);
}

TEST(V2XOvertakeCoreMissionOwnership, SameSidePassReplacementContinuesPass)
{
  EXPECT_EQ(
    resolve_paused_replacement_execution_mode(
      PausedExecutionOrigin::Pass, false),
    PausedReplacementExecutionMode::ContinuePass);

  EXPECT_EQ(
    resolve_paused_replacement_execution_mode(
      PausedExecutionOrigin::Pass, true),
    PausedReplacementExecutionMode::RestartShiftOut);
  EXPECT_EQ(
    resolve_paused_replacement_execution_mode(
      PausedExecutionOrigin::ShiftOut, false),
    PausedReplacementExecutionMode::RestartShiftOut);
  EXPECT_EQ(
    resolve_paused_replacement_execution_mode(
      PausedExecutionOrigin::Recovery, false),
    PausedReplacementExecutionMode::RestartShiftOut);
}

TEST(V2XOvertakeCoreMissionOwnership, SafetyBrakePauseResumeRejectsHardFaults)
{
  PausedExecutionResumeRequest request;
  request.safety_brake_pause = true;
  request.origin = PausedExecutionOrigin::Pass;
  request.validated_frozen_path = true;
  request.mission_side_valid = true;
  request.body_clear_deadline_checked = true;
  request.body_clear_deadline_feasible = true;
  request.target_seen = true;

  const auto expect_hold = [&]() {
      EXPECT_EQ(
        resolve_paused_execution_resume(request),
        PausedExecutionResumeAction::Hold);
    };

  request.dynamic_mission_wait_active = true;
  expect_hold();
  request.dynamic_mission_wait_active = false;
  request.target_position_jump = true;
  expect_hold();
  request.target_position_jump = false;
  request.target_course_progress_discontinuity = true;
  expect_hold();
  request.target_course_progress_discontinuity = false;
  request.target_pass_side_intrusion = true;
  expect_hold();
  request.target_pass_side_intrusion = false;
  request.forbidden_waypoint = true;
  expect_hold();
  request.forbidden_waypoint = false;
  request.emergency_front_risk = true;
  expect_hold();
  request.emergency_front_risk = false;
  request.solver_recovery_requested = true;
  expect_hold();
  request.solver_recovery_requested = false;
  request.mission_invalidated = true;
  expect_hold();
  request.mission_invalidated = false;
  request.physical_path_hard_fault = true;
  expect_hold();
  request.physical_path_hard_fault = false;
  request.origin = PausedExecutionOrigin::Recovery;
  expect_hold();
}

TEST(V2XOvertakeCoreMissionOwnership, WallActionsKeepExistingPriority)
{
  OvertakeLineTransitionRequest request;
  request.actual_wall_physical_contact = true;
  request.actual_wall_margin_blocked = true;
  request.starting_execution_phase = true;
  request.side_replan_ready = true;
  request.shiftout_phase = true;
  request.behavior_overtake = true;
  request.side_replan_candidate_sign = -1;
  request.mission_side_sign = 1;
  EXPECT_EQ(
    resolve_overtake_line_transition(request),
    OvertakeLineTransitionAction::RecoverPhysicalWallContact);

  request.actual_wall_physical_contact = false;
  EXPECT_EQ(
    resolve_overtake_line_transition(request),
    OvertakeLineTransitionAction::RejectEntryWallMargin);

  request.starting_execution_phase = false;
  request.active_execution_phase = true;
  EXPECT_EQ(
    resolve_overtake_line_transition(request),
    OvertakeLineTransitionAction::RecoverWallMargin);
}

TEST(V2XOvertakeCoreMissionOwnership, CompletedPassHoldsSideUntilNominalRearClear)
{
  OvertakeLineTransitionRequest request;
  request.actual_wall_margin_blocked = true;
  request.completed_pass_ready_to_return_before_margin_recovery = true;
  EXPECT_EQ(
    resolve_overtake_line_transition(request),
    OvertakeLineTransitionAction::HoldPassForRearClearBeforeWallMarginRecovery);

  request.rear_clear_confirmed = true;
  EXPECT_EQ(
    resolve_overtake_line_transition(request),
    OvertakeLineTransitionAction::ReturnBeforeWallMarginRecovery);

  request.rear_clear_confirmed = false;
  request.completed_pass_ready_to_return_before_margin_recovery = false;
  request.completed_pass_waiting_for_return_corridor = true;
  EXPECT_EQ(
    resolve_overtake_line_transition(request),
    OvertakeLineTransitionAction::HoldCompletedPassForReturnCorridor);

  request.actual_wall_sample_unavailable = true;
  EXPECT_EQ(
    resolve_overtake_line_transition(request),
    OvertakeLineTransitionAction::RecoverWallMargin);
}

TEST(V2XOvertakeCoreMissionOwnership, ReturnCancellationPrecedesWallAndSideActions)
{
  OvertakeLineTransitionRequest request;
  request.cancel_early_return_for_corridor_blocker = true;
  request.actual_wall_margin_blocked = true;
  request.completed_pass_ready_to_return_before_margin_recovery = true;
  request.side_replan_ready = true;
  request.shiftout_phase = true;
  request.behavior_overtake = true;
  request.side_replan_candidate_sign = -1;
  request.mission_side_sign = 1;

  EXPECT_EQ(
    resolve_overtake_line_transition(request),
    OvertakeLineTransitionAction::ResumePassForReturnCorridorBlocker);
}

TEST(V2XOvertakeCoreMissionOwnership, SideAndPassActionsKeepExistingPriority)
{
  OvertakeLineTransitionRequest request;
  request.side_replan_ready = true;
  request.side_replan_abort = true;
  request.shiftout_phase = true;
  request.behavior_overtake = true;
  request.side_replan_candidate_sign = -1;
  request.mission_side_sign = 1;
  request.pass_phase = true;
  request.rear_clear_confirmed = true;
  request.pass_progress_watchdog_timed_out = true;
  EXPECT_EQ(
    resolve_overtake_line_transition(request),
    OvertakeLineTransitionAction::ReplanEarlyShiftOutSide);

  request.side_replan_ready = false;
  EXPECT_EQ(
    resolve_overtake_line_transition(request),
    OvertakeLineTransitionAction::RecoverOccupiedPassSide);

  request.side_replan_abort = false;
  EXPECT_EQ(
    resolve_overtake_line_transition(request),
    OvertakeLineTransitionAction::ReturnRearClear);

  request.return_corridor_blocked = true;
  EXPECT_EQ(
    resolve_overtake_line_transition(request),
    OvertakeLineTransitionAction::RecoverLongitudinalProgress);

  request.pass_progress_watchdog_timed_out = false;
  EXPECT_EQ(
    resolve_overtake_line_transition(request),
    OvertakeLineTransitionAction::None);
}

TEST(V2XOvertakeCoreMissionDiagnostics, TransitionActionNamesAreStable)
{
  using multi_purpose_mpc_ros::v2x_overtake_core::to_string;

  EXPECT_STREQ(to_string(OvertakeLineTransitionAction::None), "None");
  EXPECT_STREQ(
    to_string(OvertakeLineTransitionAction::RecoverPhysicalWallContact),
    "RecoverPhysicalWallContact");
  EXPECT_STREQ(
    to_string(OvertakeLineTransitionAction::RejectEntryWallMargin),
    "RejectEntryWallMargin");
  EXPECT_STREQ(
    to_string(OvertakeLineTransitionAction::ResumePassForReturnCorridorBlocker),
    "ResumePassForReturnCorridorBlocker");
  EXPECT_STREQ(
    to_string(
      OvertakeLineTransitionAction::HoldPassForRearClearBeforeWallMarginRecovery),
    "HoldPassForRearClearBeforeWallMarginRecovery");
  EXPECT_STREQ(
    to_string(OvertakeLineTransitionAction::ReturnBeforeWallMarginRecovery),
    "ReturnBeforeWallMarginRecovery");
  EXPECT_STREQ(
    to_string(OvertakeLineTransitionAction::HoldCompletedPassForReturnCorridor),
    "HoldCompletedPassForReturnCorridor");
  EXPECT_STREQ(
    to_string(OvertakeLineTransitionAction::RecoverWallMargin),
    "RecoverWallMargin");
  EXPECT_STREQ(
    to_string(OvertakeLineTransitionAction::ReplanEarlyShiftOutSide),
    "ReplanEarlyShiftOutSide");
  EXPECT_STREQ(
    to_string(OvertakeLineTransitionAction::RecoverOccupiedPassSide),
    "RecoverOccupiedPassSide");
  EXPECT_STREQ(
    to_string(OvertakeLineTransitionAction::ReturnRearClear),
    "ReturnRearClear");
  EXPECT_STREQ(
    to_string(OvertakeLineTransitionAction::RecoverLongitudinalProgress),
    "RecoverLongitudinalProgress");
}

TEST(V2XOvertakeCoreMissionDiagnostics, LogsOnlyAtActionEventBoundary)
{
  const auto wall_action =
    OvertakeLineTransitionAction::RecoverPhysicalWallContact;
  const auto margin_action =
    OvertakeLineTransitionAction::RecoverWallMargin;

  EXPECT_FALSE(should_log_overtake_line_transition_action(
      OvertakeLineTransitionAction::None,
      OvertakeLineTransitionAction::None));
  EXPECT_TRUE(should_log_overtake_line_transition_action(
      wall_action, OvertakeLineTransitionAction::None));
  EXPECT_FALSE(should_log_overtake_line_transition_action(
      wall_action, wall_action));
  EXPECT_TRUE(should_log_overtake_line_transition_action(
      margin_action, wall_action));
  EXPECT_TRUE(should_log_overtake_line_transition_action(
      wall_action, OvertakeLineTransitionAction::None));
}

