TEST(V2XOvertakeCoreCommitStage, KeepsSideSelectableUntilMissionFreeze)
{
  PassCommitStageRequest request;
  request.target_front_distance_m = 4.0;
  request.side_by_side_no_return_front_distance_m = 2.0;

  auto resolution = resolve_pass_commit_stage(request);
  ASSERT_TRUE(resolution.valid);
  EXPECT_EQ(resolution.stage, PassCommitStage::Selectable);
  EXPECT_TRUE(resolution.side_replan_allowed);

  request.frozen_execution_active = true;
  resolution = resolve_pass_commit_stage(request);
  ASSERT_TRUE(resolution.valid);
  EXPECT_EQ(resolution.stage, PassCommitStage::ShiftCommitted);
  EXPECT_TRUE(resolution.side_replan_allowed);
}

TEST(V2XOvertakeCoreCommitStage, FixesSideAtNoReturnOrForwardCommit)
{
  PassCommitStageRequest request;
  request.frozen_execution_active = true;
  request.target_front_distance_m = 1.99;
  request.side_by_side_no_return_front_distance_m = 2.0;

  auto resolution = resolve_pass_commit_stage(request);
  ASSERT_TRUE(resolution.valid);
  EXPECT_EQ(resolution.stage, PassCommitStage::SideBySideCommitted);
  EXPECT_FALSE(resolution.side_replan_allowed);

  request.target_front_distance_m = 4.0;
  request.lateral_clearance_latched = true;
  resolution = resolve_pass_commit_stage(request);
  EXPECT_EQ(resolution.stage, PassCommitStage::ShiftCommitted);
  EXPECT_TRUE(resolution.side_replan_allowed);

  request.forward_completion_latched = true;
  resolution = resolve_pass_commit_stage(request);
  EXPECT_EQ(resolution.stage, PassCommitStage::SideBySideCommitted);

  request.rear_clear = true;
  resolution = resolve_pass_commit_stage(request);
  EXPECT_EQ(resolution.stage, PassCommitStage::RearClear);

  request.side_by_side_no_return_front_distance_m = -0.1;
  EXPECT_FALSE(resolve_pass_commit_stage(request).valid);
}

TEST(V2XOvertakeCoreCommitStage, CrossSideNoReturnRemainsLatchedWhenTargetMovesAway)
{
  CrossSideNoReturnLatchRequest request;
  request.execution_active = true;
  request.observed_stage = PassCommitStage::SideBySideCommitted;
  EXPECT_TRUE(resolve_cross_side_no_return_latch(request));

  request.previously_latched = true;
  request.observed_stage = PassCommitStage::ShiftCommitted;
  EXPECT_TRUE(resolve_cross_side_no_return_latch(request));

  request.previously_latched = false;
  request.safe_separation_active = true;
  EXPECT_TRUE(resolve_cross_side_no_return_latch(request));

  request.safe_separation_active = false;
  request.side_replacement_committed = true;
  EXPECT_TRUE(resolve_cross_side_no_return_latch(request));

  request.side_replacement_committed = false;
  request.previously_latched = true;
  request.observed_stage = PassCommitStage::ShiftCommitted;
  EXPECT_TRUE(resolve_cross_side_no_return_latch(request));
}

TEST(V2XOvertakeCoreCommitStage, CrossSideMinimumSpeedUsesCurrentStateWhenTargetIsFaster)
{
  EXPECT_NEAR(
    resolve_cross_side_minimum_speed_requirement(1.39, 3.02), 1.39, 1e-9);
  EXPECT_NEAR(
    resolve_cross_side_minimum_speed_requirement(5.0, 3.02), 3.02, 1e-9);
  EXPECT_NEAR(
    resolve_cross_side_minimum_speed_requirement(0.0, 3.02), 0.0, 1e-9);
}

TEST(V2XOvertakeCoreCommitStage, CrossSideMinimumSpeedRejectsInvalidInputs)
{
  EXPECT_FALSE(std::isfinite(
    resolve_cross_side_minimum_speed_requirement(-0.1, 3.0)));
  EXPECT_FALSE(std::isfinite(
    resolve_cross_side_minimum_speed_requirement(1.0, -0.1)));
  EXPECT_FALSE(std::isfinite(resolve_cross_side_minimum_speed_requirement(
    std::numeric_limits<double>::quiet_NaN(), 3.0)));
}

